"""Archive matched contraction measurements without changing historical records."""

import difflib
import hashlib
import json
import math
import statistics
from pathlib import Path

ROOT = Path("/tmp/contraction-performance-next")
REPO = Path("/common/dev/gammaloop/feynkit-rich-display")
TARGET = REPO / "examples/notebooks/contraction_performance.json"
FULL_DRIVER = "crates/idenso/examples/metric_contraction_benchmark.rs"
PHASE_DRIVER = "crates/idenso/examples/contraction_phase_benchmark.rs"


def digest(path):
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def identity(path):
    return {"path": str(path), "bytes": path.stat().st_size, "sha256": digest(path)}


def read_json(path):
    return json.loads(path.read_text())


def rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def compare(before_path, after_path, fields, expected_rows):
    before, after = rows(before_path), rows(after_path)
    maps = [
        {tuple(row[field] for field in fields): row for row in phase}
        for phase in [before, after]
    ]
    assert len(before) == len(after) == len(maps[0]) == len(maps[1]) == expected_rows
    assert maps[0].keys() == maps[1].keys()
    comparison = []
    for phase in [before, after]:
        for row in phase:
            assert len(row["samples_ns"]) == 5
            assert all(
                math.isfinite(value) and value > 0 for value in row["samples_ns"]
            )
            assert math.isclose(
                statistics.median(row["samples_ns"]), row["median_ns"], rel_tol=1e-12
            )
    for key, old in maps[0].items():
        new = maps[1][key]
        assert old["terms"] == new["terms"], key
        comparison.append(
            {
                **dict(zip(fields, key)),
                "before_ms": old["median_ns"] / 1e6,
                "after_ms": new["median_ns"] / 1e6,
                "speedup": old["median_ns"] / new["median_ns"],
                "before_output_terms": old["output_terms"],
                "after_output_terms": new["output_terms"],
                "before_changed": old["changed"],
                "after_changed": new["changed"],
            }
        )
    return {"before": before, "after": after, "comparison": comparison}


def snapshots(before_directory, after_directory):
    directories = {"before": before_directory, "after": after_directory}
    checksums = {
        phase: {
            path.name: digest(path)
            for path in sorted(directory.iterdir())
            if path.is_file()
        }
        for phase, directory in directories.items()
    }
    assert checksums["before"].keys() == checksums["after"].keys()
    differences = []
    for name, old in checksums["before"].items():
        if old == checksums["after"][name]:
            continue
        difference = {
            "file": name,
            "before_sha256": old,
            "after_sha256": checksums["after"][name],
        }
        for phase, directory in directories.items():
            path = directory / name
            if path.stat().st_size < 12000:
                difference[phase] = path.read_text()
        differences.append(difference)
    assert not any(
        row["file"].endswith((".input", ".gamma_input", ".source"))
        for row in differences
    )
    return {
        "sha256": checksums,
        "summary": {
            "total": len(checksums["before"]),
            "different": len(differences),
            "identical": len(checksums["before"]) - len(differences),
        },
        "differences": differences,
    }


def main():
    baseline = read_json(ROOT / "before.json")
    assert digest(ROOT / "before") == baseline["executable"]["sha256"]
    for name, checksum in baseline["source_sha256"].items():
        assert digest(ROOT / "before-source" / name) == checksum, name
    assert digest(REPO / FULL_DRIVER) == baseline["source_sha256"][FULL_DRIVER]
    assert (REPO / PHASE_DRIVER).read_text() == (ROOT / "phases/driver.rs").read_text()
    full = compare(
        ROOT / "confirmation-before.jsonl",
        ROOT / "confirmation-after.jsonl",
        ["case", "method"],
        641,
    )
    first_full = compare(
        ROOT / "before.jsonl", ROOT / "after.jsonl", ["case", "method"], 641
    )
    phases = compare(
        ROOT / "phases/before.jsonl",
        ROOT / "phases/after.jsonl",
        ["case", "input_variant", "method"],
        860,
    )
    full["snapshots"] = snapshots(
        ROOT / "confirmation-before-output", ROOT / "confirmation-after-output"
    )
    first_snapshots = snapshots(ROOT / "before-output", ROOT / "after-output")
    assert first_snapshots["sha256"] == full["snapshots"]["sha256"]
    first_full["snapshot_summary"] = first_snapshots["summary"]
    first_full["snapshot_hashes_match_confirmation"] = True
    phases["snapshots"] = snapshots(
        ROOT / "phases/before-output", ROOT / "phases/after-output"
    )
    assert full["snapshots"]["summary"]["total"] == 787
    assert phases["snapshots"]["summary"]["total"] == 952
    form = read_json(ROOT / "form/summary.json")
    assert len(form["records"]) == 15
    assert (
        sum(row["historical_polynomial_identical"] is True for row in form["records"])
        == 12
    )
    form_by_case = {row["idenso_case"]: row for row in form["records"]}
    for row in full["comparison"]:
        output = f"{row['case']}.{row['method']}.output"
        row["output_identical"] = (
            full["snapshots"]["sha256"]["before"][output]
            == full["snapshots"]["sha256"]["after"][output]
        )
        if row["method"] == "full_gamma" and row["case"] in form_by_case:
            form_ms = form_by_case[row["case"]]["wall_ns_median"] / 1e6
            row.update(form_wall_ms=form_ms, after_over_form=row["after_ms"] / form_ms)
    for row in phases["comparison"]:
        output = f"{row['case']}.{row['input_variant']}.{row['method']}.output"
        row["output_identical"] = (
            phases["snapshots"]["sha256"]["before"][output]
            == phases["snapshots"]["sha256"]["after"][output]
        )
    sources = baseline["source_sha256"]
    after_sources = {name: digest(REPO / name) for name in sources}
    changes = {}
    for name, old_hash in sources.items():
        if old_hash == after_sources[name]:
            continue
        old = (ROOT / "before-source" / name).read_text()
        new = (REPO / name).read_text()
        changes[name] = {
            "before_sha256": old_hash,
            "after_sha256": after_sources[name],
            "patch": "".join(
                difflib.unified_diff(
                    old.splitlines(keepends=True),
                    new.splitlines(keepends=True),
                    fromfile=f"before/{name}",
                    tofile=f"after/{name}",
                )
            ),
        }
    oracle_name = "crates/spenso-hep-lib/tests/short_trace_validation.rs"
    old_oracle = ROOT / "before-source/short_trace_validation.rs"
    new_oracle = REPO / oracle_name
    after_sources[oracle_name] = digest(new_oracle)
    changes[oracle_name] = {
        "before_sha256": digest(old_oracle),
        "after_sha256": digest(new_oracle),
        "patch": "".join(
            difflib.unified_diff(
                old_oracle.read_text().splitlines(keepends=True),
                new_oracle.read_text().splitlines(keepends=True),
                fromfile=f"before/{oracle_name}",
                tofile=f"after/{oracle_name}",
            )
        ),
    }
    for name, checksum in read_json(
        ROOT / "validated-performance-sources.json"
    ).items():
        assert digest(REPO / name) == checksum, name
    for name, checksum in read_json(ROOT / "measured-after-source-sha256.json").items():
        assert digest(REPO / name) == checksum, name
    artifacts = rows(ROOT / "after-artifacts.jsonl")
    assert any(
        row.get("reason") == "build-finished" and row.get("success")
        for row in artifacts
    )
    packages = {
        row["target"]["name"]: row
        for row in artifacts
        if row.get("reason") == "compiler-artifact"
        and row["target"]["name"]
        in [
            "idenso",
            "spenso",
            "symbolica",
            "symbolica_utils",
            "metric_contraction_benchmark",
            "contraction_phase_benchmark",
        ]
    }
    assert baseline["symbolica_revision"] in packages["symbolica"]["package_id"]
    for name in ["metric_contraction_benchmark", "contraction_phase_benchmark"]:
        assert packages[name]["executable"]
    assert digest(
        Path(packages["metric_contraction_benchmark"]["executable"])
    ) == digest(ROOT / "after")
    record = {
        "schema_version": 1,
        "date": "2026-09-24",
        "scope": "Matched contraction and gamma-pipeline improvements on unchanged Symbolica 06906976. Physical factorization is retained; printed-output agreement and HEP component tests establish regression evidence, not term counts alone.",
        "symbolica_revision": baseline["symbolica_revision"],
        "baseline": baseline,
        "historical_record": identity(
            REPO / "examples/notebooks/symbolica_main_update.json"
        ),
        "full_driver": {
            "path": FULL_DRIVER,
            "source": (REPO / FULL_DRIVER).read_text(),
            "cases": 73,
            "rows_per_phase": 641,
            **full,
        },
        "first_full_pair": {
            "scope": "Retained initial pair. A contiguous shared-host transient raised unchanged parser/normalizer controls by about1.6x in the after run; the full driver was repeated after-before. Main full comparison uses that confirmation, while these original raw samples remain available.",
            **first_full,
        },
        "phase_driver": {
            "path": PHASE_DRIVER,
            "source": (REPO / PHASE_DRIVER).read_text(),
            "input_shapes": 92,
            "rows_per_phase": 860,
            "scope": "Public linked stages on73 fixtures/terminal outputs,16 original gamma inputs and3 embedded factored generic controls. Stage timings overlap and are not additive. Original and terminal gamma calls can take different paths.",
            **phases,
        },
        "form": form,
        "form_reproduction": {
            "script": (ROOT / "form/measure.py").read_text(),
            "inputs": read_json(ROOT / "form/inputs.json"),
        },
        "timing_method": "Five warm samples per Rust method with adaptive batches targeting 8 ms, CPU 6, output destruction included. Input preparation and exact output validation are outside timing. The primary full table uses reversed after-before confirmation after unchanged controls exposed a localized transient in the initial before-after pair; both pairs are retained. Phase measurements use the original before-after pair; fresh FORM usesCPU 3. Our builds were quiet; unrelated shared-host activity was neither controlled nor paused. FORM has one warmup plus three measured processes, six batches each; amortized wall includes startup/input preparation and internal CPU covers trace4 plus sorting.",
        "after_source_sha256": after_sources,
        "source_changes": changes,
        "after_compiler_artifacts": packages,
        "executables": {
            name: identity(ROOT / path)
            for name, path in {
                "full_before": "before",
                "full_after": "after",
                "phase_before": "phases/before",
                "phase_after": "phases/after",
            }.items()
        },
        "measurement_plan": read_json(ROOT / "measurement-plan.json"),
        "aggregation_script": Path(__file__).read_text(),
    }
    for name, path in {
        "measurement": "measurement.json",
        "confirmation_measurement": "confirmation-measurement.json",
        "validation_runs": "validation-runs.json",
        "validation": "validation.json",
        "final_hep_validation": "final-hep-validation.json",
        "validated_performance_sources": "validated-performance-sources.json",
        "benchmark_build_performance_sources": "frozen-performance-sources.json",
        "measured_after_sources": "measured-after-source-sha256.json",
        "phase_before_build": "phases/before-build-command.json",
        "phase_after_build": "phases/after-build-command.json",
        "slot_contractor_probe": "slot-probe/summary.json",
        "slot_contractor_validation": "slot-probe/validation.json",
    }.items():
        if (ROOT / path).exists():
            record[name] = read_json(ROOT / path)
    record["validation_scope"] = {
        "fresh_passing_tests": 383,
        "idenso_passing_tests": 344,
        "hep_passing_tests": 39,
        "known_idenso_snapshot_failures": 1,
        "skipped_tests": 23,
        "spenso_tests_rerun": False,
        "clippy": "Both scoped Idenso and final HEP checks pass with warnings denied.",
        "timings": "Validation driver elapsed values include compilation and, for the initial HEP stage, an explicit parent pause; they are not benchmark/test-runtime measurements.",
        "resolved_oracle_timeout": "The first explicit axial-12 HEP oracle created a large rank-12 intermediate and timed out. The final independent oracle binds the same vectors inside each raw gamma before the HEP matrix trace; all 39 HEP tests pass. Only this test source changed after benchmark compilation; production source identities remain exact.",
        "initial_timeout_log": identity(ROOT / "hep-tests-initial-timeout.log"),
        "initial_timeout_source": {
            **identity(ROOT / "timedout-short-trace-validation.rs"),
            "contents": (ROOT / "timedout-short-trace-validation.rs").read_text(),
        },
        "final_oracle_source": {
            **identity(new_oracle),
            "contents": new_oracle.read_text(),
        },
    }
    record["documentation_validation"] = read_json(ROOT / "documentation-validation.json")
    TARGET.write_text(json.dumps(record, indent=2) + "\n")
    print("Wrote", TARGET, full["snapshots"]["summary"], phases["snapshots"]["summary"])
    for row in full["comparison"]:
        if row["method"] == "full_gamma":
            print(
                row["case"],
                row["before_ms"],
                row["after_ms"],
                row["speedup"],
                row.get("after_over_form"),
            )


if __name__ == "__main__":
    main()

