    gamma_trace_5: 5, gamma_trace_6: 6, gamma_trace_7: 7, gamma_trace_8: 8,
    gamma_trace_9: 9, gamma_trace_10: 10, gamma_trace_11: 11, gamma_trace_12: 12,
    gamma_trace_13: 13, gamma_trace_14: 14,
