    let bis = Bispinor {}.new_rep(4);
    let [a, b, c, d] = TraceEvaluation::ordering_slots();
    let repeated = spenso::trace!(&bis; evaluations[0].ordering_factors());
    let mut factors = evaluations[0].ordering_factors();
    factors[5] = idenso::gamma!(&c);
